#include "staged_lm/binary_io.h"
#include "staged_lm/pose_shape_lm.h"
#include <filesystem>
#include <cmath>
#include <fstream>
#include <iostream>
namespace {using namespace staged_lm;std::filesystem::path arg(int n,char**v,const std::string&k){for(int i=1;i+1<n;++i)if(v[i]==k)return v[i+1];throw std::runtime_error("missing "+k);}int iv(const std::map<std::string,std::string>&m,const std::string&k){return std::stoi(m.at(k));}float fv(const std::map<std::string,std::string>&m,const std::string&k){return std::stof(m.at(k));}PoseShapeCameraInput camera(const std::filesystem::path&f,const std::map<std::string,std::string>&m,const std::vector<float>&p,const std::string&c){int n=iv(m,c+"_count");PoseShapeCameraInput x;x.pose.camera=c;x.pose.parameters={p.begin(),p.begin()+75};x.pose.point_count=n;x.pose.left_hand_pose=read_float32_file(f/(c+"_left_hand_pose.f32"),45);x.pose.right_hand_pose=read_float32_file(f/(c+"_right_hand_pose.f32"),45);x.pose.scale=read_float32_file(f/(c+"_scale.f32"),1)[0];x.pose.selected_posedirs=read_float32_file(f/(c+"_selected_posedirs.f32"),486*n*3);x.pose.selected_lbs_weights=read_float32_file(f/(c+"_selected_lbs_weights.f32"),n*55);x.pose.targets=read_float32_file(f/(c+"_targets.f32"),n*2);x.pose.image_width=iv(m,"image_width");x.pose.image_height=iv(m,"image_height");x.selected_base_v_shaped=read_float32_file(f/(c+"_selected_base_v_shaped.f32"),n*3);x.selected_beta_shapedirs=read_float32_file(f/(c+"_selected_beta_shapedirs.f32"),n*3*10);return x;}}
int main(int argc,char**argv){try{auto f=arg(argc,argv,"--fixture"),o=arg(argc,argv,"--output");auto m=read_key_value_file(f/"fixture_meta.txt");PoseShapeLMProblem p;p.initial_parameters=read_float32_file(f/"parameters.f32",85);p.base_joints=read_float32_file(f/"base_joints.f32",165);p.joint_basis=read_float32_file(f/"d_joints_d_beta.f32",1650);p.beta_anchor=read_float32_file(f/"beta_anchor.f32",10);p.body_pose_anchor=read_float32_file(f/"body_pose_anchor.f32",63);p.parents=read_int64_file(f/"parents.i64",55);p.cam2=camera(f,m,p.initial_parameters,"cam2");p.cam4=camera(f,m,p.initial_parameters,"cam4");p.beta_limit=fv(m,"beta_abs_limit");p.normal_config.charbonnier_eps=fv(m,"charbonnier_eps");p.normal_config.cam2_alpha_per_point=fv(m,"cam2_alpha");p.normal_config.cam4_alpha_per_point=fv(m,"cam4_alpha");p.normal_config.pose_anchor_scale=fv(m,"pose_anchor_scale");p.normal_config.shape_anchor_scale=fv(m,"shape_anchor_scale");p.lm_config={85,iv(m,"lm_max_accepted_steps"),iv(m,"lm_max_trials"),std::stod(m["rel_objective_tolerance"]),std::stod(m["scaled_gradient_tolerance"]),std::stod(m["step_tolerance"])};auto r=run_pose_shape_lm(p);std::filesystem::create_directories(o);write_float32_file(o/"initial_parameters.f32",r.initial_parameters);write_float32_file(o/"final_parameters.f32",r.final_parameters);write_float32_file(o/"final_beta_latent.f32",{r.final_parameters.begin()+75,r.final_parameters.end()});std::vector<float>physical(10);for(int b=0;b<10;++b)physical[b]=p.beta_limit*std::tanh(r.final_parameters[75+b]);write_float32_file(o/"final_physical_beta.f32",physical);std::ofstream ts(o/"trajectory.tsv");ts<<"index\touter\ttrial\tlambda_before\tsolve_backend\tsolve_success\tcandidate_objective\tpredicted\tactual\trho\taccepted\tlambda_after\n";for(auto&t:r.trials){ts<<t.index<<'\t'<<t.outer<<'\t'<<t.trial<<'\t'<<t.lambda_before<<'\t'<<t.solve_backend<<'\t'<<t.solve_success<<'\t'<<t.candidate_objective<<'\t'<<t.predicted_reduction<<'\t'<<t.actual_reduction<<'\t'<<t.rho<<'\t'<<t.accepted<<'\t'<<t.lambda_after<<'\n';write_float64_file(o/("trial_"+std::to_string(t.index)+"_delta_double.f64"),t.delta_double);write_float32_file(o/("trial_"+std::to_string(t.index)+"_delta_float.f32"),t.delta_float);write_float32_file(o/("trial_"+std::to_string(t.index)+"_candidate.f32"),t.candidate);}write_key_value_file(o/"counters.txt",{{"accepted_steps",std::to_string(r.accepted_steps)},{"rejected_trials",std::to_string(r.rejected_trials)},{"objective_call_count",std::to_string(r.objective_call_count)},{"linearization_call_count",std::to_string(r.normal_equation_call_count)},{"structured_solve_calls",std::to_string(r.solve_call_count)},{"dense_fallback_calls","0"},{"total_trials",std::to_string(r.trials.size())},{"status",r.status},{"convergence_branch",r.convergence_branch},{"initial_objective",std::to_string(r.initial_objective)},{"final_objective",std::to_string(r.final_objective)},{"initial_lambda",std::to_string(r.initial_lambda)},{"final_lambda",std::to_string(r.final_lambda)}});write_key_value_file(o/"timing.txt",{{"initial_objective_ms",std::to_string(r.initial_objective_ms)},{"total_objective_ms",std::to_string(r.total_objective_ms)},{"total_jacobian_ms",std::to_string(r.total_jacobian_ms)},{"total_structured_ne_ms",std::to_string(r.total_normal_equations_ms)},{"total_schur_ms",std::to_string(r.total_solve_ms)},{"total_control_ms",std::to_string(r.total_control_ms)},{"total_lm_ms",std::to_string(r.total_lm_ms)}});std::cout<<"POSE_SHAPE_LM_REFERENCE_WRITTEN status="<<r.status<<" trials="<<r.trials.size()<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
